from taf.hw.pdu import pdu

from .exception import InvalidInputParameter, BadDeviceStatus


class ute_pdu:
    """
    This library supports multiple setups where each setup can be specified by **alias** argument for every keyword.
    This argument can be specified as follows:
       ::

           Setup Pdu    host_ip=${tl.fsm.pdu.addr}    model=${tl.fsm.pdu.device}    alias=PDU_TL101


    SNMPv3 is supported by providing user configuration.
    This argument can be specified as follows:
       ::

           Setup Pdu    host_ip=${tl.fsm.pdu.addr}    model=${tl.fsm.pdu.device}    snmp_user=${tl.fsm.pdu.snmp_user}

       More examples are available in attached Robot Framework example files.
    """

    ROBOT_LIBRARY_SCOPE = "TEST SUITE"

    def __init__(self):
        self.taf_hw_pdu = pdu()

    def setup_pdu(self, host: str, model: str, timeout=20, **kwargs):
        """Prepare library to work with specified PDU device.

        It is possible to execute "on", "off", "get status" and "reset" on specified PDU outlet.

        :param string host:  IP address or domain name of pdu.
        :param string model:    Type of device (APC/SWH/ATEN/DCS).
        :param float timeout:   Maximum number of seconds to wait for expected pdu status.
        |

        :Supported parameters are available via kwargs:
            * ** version **    (string)   -  A specific version of the device, e.g., '8220-1' for EPC.
                                             See the list of supported devices in `taf.hw.pdu` lib documentation
            * **snmp_user**    (dict)     -  User configuration for SNMPv3 with keys:
                                             userName, authKey, privKey, authProtocol (SHA/MD5), privProtocol (AES/DES)
            * **fpfh_type**    (integer)  -  Type of FPFH PDU. Available types: 1, 2
            * **protocol**     (dict)     -  Protocol for FPFH PDU. Available protocols: 'snmp', 'http'

        :note: PDU port number can be specified in kwargs as: port=<port-number>.
                If no port is specified, default will be used as specified by each PDU's technical documentation.
        """
        alias = kwargs.pop("alias", None)
        return self.taf_hw_pdu.setup_pdu(model, host, alias, timeout=timeout, **kwargs)

    def teardown_pdu(self, **kwargs):
        """Clean up information about PDU device defined in setup_pdu."""
        alias = kwargs.get("alias", None)
        return self.taf_hw_pdu.teardown_pdu(pdu_device=alias)

    def pdu_outlet_off(self, outlet, **kwargs):
        """Execute the (OFF) action on given pdu outlet.

        :param integer outlet:    Pdu outlet to be turned off.
        """
        alias = kwargs.get("alias", None)
        return self.taf_hw_pdu.power_off(outlet, pdu_device=alias)

    def pdu_outlet_on(self, outlet, **kwargs):
        """Execute the (ON) action on given pdu outlet.

        :param integer outlet:    Pdu outlet to be turned on.
        """
        alias = kwargs.get("alias", None)
        return self.taf_hw_pdu.power_on(outlet, pdu_device=alias)

    def pdu_outlet_reset(self, outlet, time_interval=10, **kwargs):
        """Reset given pdu outlet.

        :param integer outlet:        Pdu outlet to be reset.
        :param int|float time_interval:   Time between the OFF/ON actions.
        """
        alias = kwargs.get("alias", None)
        return self.taf_hw_pdu.reset_ports([outlet], time_interval=time_interval, pdu_device=alias)

    def get_pdu_outlet_status(self, outlet, **kwargs):
        """Get pdu outlet status.

        :param integer outlet:     Pdu output whose status should be returned

        :return:                 Pdu output state (on/off).
        :rtype:                  string
        """
        alias = kwargs.get("alias", None)
        return self.taf_hw_pdu.get_port_status(outlet, pdu_device=alias)

    def pdu_outlet_should_be(self, outlet, status, **kwargs):
        """Raise exception if given outlet status is other than expected.

        :param integer outlet:      Pdu outlet number to be checked.
        :param string  status:      Expected output status (on/off).

        :raise:                     PDUError is raised if status is other than expected.
        """
        alias = kwargs.get("alias", None)
        current_state = self.taf_hw_pdu.get_port_status(outlet, pdu_device=alias)
        if current_state != status:
            raise BadDeviceStatus(
                "Outlet %d status is %s, and should be %s" % (outlet, current_state, status)
            )

    def reset_pdu_outlets(self, outlets, time_interval=10, **kwargs):
        """Resets range of PDU outlets as specified by outlets

        :param  list   outlets:        List of PDU outlets to reset
        :param  float  time_interval:  Time in seconds between OFF/ON actions

        :raise:                        PDUException if no outlets specified, or outlets is empty
        """
        if len(outlets) == 0:
            raise InvalidInputParameter("No outlets specified.")
        alias = kwargs.get("alias", None)
        return self.taf_hw_pdu.reset_ports(outlets, time_interval=time_interval, pdu_device=alias)

    def get_voltage(self, **kwargs):
        """Get voltage from PSU.
        Currently working for SCPI PDU GW INSTEK PSU 60-25
        :no param
        """
        alias = kwargs.get("alias", None)
        return self.taf_hw_pdu.get_voltage(pdu_device=alias, port=999)  # port inconsequential

    def set_voltage(self, voltage, **kwargs):
        """Set voltage for PSU.
        Currently working for SCPI PDU GW INSTEK PSU 60-25
        :param voltage:             int value for voltage to be set on PDU, range is 35-60.
        :raise:                     ScpiOutputReadingError if voltage could not be read.
        :raise:                     VoltageNotInRange if voltage is not in range.
        """
        alias = kwargs.get("alias", None)
        return self.taf_hw_pdu.set_voltage(999, voltage, pdu_device=alias)  # port inconsequential
